def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the solid 3-colored band.
    row_band = [r for r in range(h) if all(v == 3 for v in grid[r])]
    col_band = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    horizontal = bool(row_band)
    band = row_band if horizontal else col_band
    if not band:
        return out

    tile = len(band)
    step = tile + 1
    row_starts = list(range(0, h - tile + 1, step))
    col_starts = list(range(0, w - tile + 1, step))
    band_start = band[0]
    band_index = (band_start // step)

    # Remove the band.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    def get_tile(ri, ci):
        r0, c0 = row_starts[ri], col_starts[ci]
        return tuple(tuple(grid[r0 + a][c0 + b] for b in range(tile))
                     for a in range(tile))

    def nonempty(pattern):
        return any(v == 2 for row in pattern for v in row)

    # Copy a tile into the band when its designated local cell is occupied.
    if horizontal:
        missing_r = band_index
        for ci in range(len(col_starts)):
            patterns = [get_tile(ri, ci) for ri in range(len(row_starts))
                        if ri != missing_r]
            patterns = [p for p in patterns if nonempty(p)]
            if not patterns:
                continue
            template = max(set(patterns), key=patterns.count)
            if template[missing_r][ci] == 2:
                r0, c0 = row_starts[missing_r], col_starts[ci]
                for a in range(tile):
                    for b in range(tile):
                        out[r0 + a][c0 + b] = template[a][b]
    else:
        missing_c = band_index
        for ri in range(len(row_starts)):
            patterns = [get_tile(ri, ci) for ci in range(len(col_starts))
                        if ci != missing_c]
            patterns = [p for p in patterns if nonempty(p)]
            if not patterns:
                continue
            template = max(set(patterns), key=patterns.count)
            if template[ri][missing_c] == 2:
                r0, c0 = row_starts[ri], col_starts[missing_c]
                for a in range(tile):
                    for b in range(tile):
                        out[r0 + a][c0 + b] = template[a][b]

    # Mark each occupied tile at its tile-coordinate cell.
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            if any(out[r0 + a][c0 + b] == 2
                   for a in range(tile) for b in range(tile)):
                mr, mc = r0 + ri, c0 + ci
                if mr < h and mc < w and out[mr][mc] == 2:
                    out[mr][mc] = 8

    return out
